        /// <summary>The projected pyramid for a country in a given year. ⚠ Years outside the published
        /// range CLAMP to the nearest published year - the publishers stop at LastYear and this table does
        /// not invent a series beyond them. What that means for a model running past LastYear is a decision
        /// for the STEP, and it is stated at the step's call site.</summary>
        public static float[] For(CountryId id, int year)
        {
            if (!Bands.TryGetValue(id, out float[][] series)) { return null; }
            int i = year - FirstYear;
            if (i < 0) { i = 0; }
            if (i >= series.Length) { i = series.Length - 1; }
            return series[i];
        }
